import sys
import tempfile
import time
import tomllib
import unittest
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency: hae/evaluation/artifacts.py
# Since it's being implemented in parallel, we assume it exists and import it.
# If it doesn't exist yet, this might fail, but the prompt implies it's available.
try:
    from hae.evaluation.artifacts import (
        filter_bundle,
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        partition_bundle,
        count_source_files
    )
except ImportError:
    # Fallback stubs if artifacts.py is not yet available in the environment
    # This ensures the module can be imported for testing the harness logic itself
    # if the dependency is missing during early development.
    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return bundle

    def is_generated_path(path: str) -> bool:
        return False

    def is_malformed_path(path: str) -> bool:
        return False

    def sanitize_path(path: str) -> str:
        return path

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        return bundle, {}, {}

    def count_source_files(bundle: Dict[str, str], suffixes: Tuple[str, ...] = ('.py',)) -> int:
        return sum(1 for p in bundle if p.endswith(suffixes))


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("Gates:")
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"  [{status_icon}] {g.name}: {g.status} ({g.method}) - {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    blocks = {}
    lines = text.split('\n')
    in_block = False
    current_path = None
    current_content = []

    # Simple regex-free parser for ```path\n...\n```
    # Assumes the first line of the block is the path if it looks like a path
    # Or we might need to look for a specific format. 
    # The spec says "fenced code blocks". Usually ```python ... ```
    # But we need a path. Let's assume the format is:
    # ```path/to/file.py
    # content
    # ```
    # Or maybe the path is inferred? No, "path->content map".
    # Let's assume the fence line contains the path.

    i = 0
    while i < len(lines):
        line = lines[i]
        if line.startswith('```'):
            if in_block:
                # End of block
                if current_path:
                    blocks[current_path] = '\n'.join(current_content)
                in_block = False
                current_path = None
                current_content = []
            else:
                # Start of block
                in_block = True
                # Try to extract path from the fence line
                # e.g. ```src/main.py
                fence_content = line[3:].strip()
                if fence_content and not fence_content.startswith('python') and not fence_content.startswith('py'):
                    # Heuristic: if it looks like a path, use it
                    # If it's just 'python', we don't have a path. 
                    # We might skip it or try to guess. 
                    # For now, if no path, we skip this block as we can't map it.
                    current_path = fence_content
                else:
                    current_path = None # No path found, skip content
                current_content = []
        elif in_block:
            if current_path is not None:
                current_content.append(line)
        i += 1

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int=DEFAULT_TIMEOUT_S, penalty_per_gate: float=DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str]=None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any=None, deliverable_text: str='') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        if workspace is not None:
            # Assume workspace is a directory path or an object with a path
            if isinstance(workspace, str):
                return self.verify_directory(workspace)
            elif hasattr(workspace, 'path'):
                return self.verify_directory(workspace.path)
            elif hasattr(workspace, 'files'):
                # Assume it's a bundle-like object
                return self.verify_bundle(workspace.files)

        # Fallback to deliverable text
        if deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            if bundle:
                return self.verify_bundle(bundle, source='deliverable')

        # Empty workspace
        return self._empty_report(source='empty')

    def verify_bundle(self, bundle: Dict[str, str], source: str='bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files
            for path, content in bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]]=None, source: str='directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        start_time = time.time()

        # 1. Identify files
        all_files = []
        for root, dirs, files in os.walk(workdir):
            # Filter out generated dirs
            dirs[:] = [d for d in dirs if not is_generated_path(os.path.join(root, d))]
            for f in files:
                full_path = os.path.join(root, f)
                rel_path = os.path.relpath(full_path, workdir)
                if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                    all_files.append(rel_path)

        # Filter for authored files if provided, otherwise use all valid files
        if authored is not None:
            # Only consider files that were in the authored bundle
            valid_authored = [p for p in all_files if p in authored]
        else:
            valid_authored = all_files

        python_files = [p for p in valid_authored if p.endswith('.py')]

        gates = []

        # Gate 1: Syntax
        gates.append(self._gate_syntax(workdir, python_files))

        # Gate 2: Build
        gates.append(self._gate_build(workdir, valid_authored))

        # Gate 3: Smoke
        gates.append(self._gate_smoke(workdir, python_files))

        # Gate 4: Tests
        gates.append(self._gate_tests(workdir, python_files))

        # Gate 5: Telemetry
        gates.append(self._gate_telemetry(workdir, python_files))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=len(valid_authored),
            python_files=len(python_files),
            source=source,
            harness_version='3.0-execution'
        )

    def _empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found'),
            GateResult(name='smoke', status=FAILED, method='import', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No tests found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No Python files found'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=5 * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def _gate_syntax(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found', duration_s=time.time()-start)

        errors = []
        for f in python_files:
            full_path = os.path.join(workdir, f)
            try:
                with open(full_path, 'r', encoding='utf-8') as file:
                    ast.parse(file.read())
            except SyntaxError as e:
                errors.append(f"{f}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='; '.join(errors), duration_s=duration)
        return GateResult(name='syntax', status=PASSED, method='ast.parse', detail='All files parsed', duration_s=duration)

    def _gate_build(self, workdir: str, authored_files: List[str]) -> GateResult:
        start = time.time()

        # Check for metadata files
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None

        for mf in metadata_files:
            if mf in authored_files:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found', duration_s=time.time()-start)

        # Validate pyproject.toml if present
        if found_metadata == 'pyproject.toml':
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(name='build', status=FAILED, method='tomllib', detail='pyproject.toml missing required tables', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='tomllib', detail=f'Invalid pyproject.toml: {e}', duration_s=time.time()-start)

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)

            # Run install
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(name='build', status=PASSED, method='pip_install', detail='Installed successfully', duration_s=duration)
            else:
                return GateResult(name='build', status=FAILED, method='pip_install', detail=f'Install failed: {result.stderr}', duration_s=duration)

        except FileNotFoundError:
            return GateResult(name='build', status=SKIPPED, method='pip_install', detail='pip not available', duration_s=time.time()-start)
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method='pip_install', detail='Install timed out', duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name='build', status=FAILED, method='pip_install', detail=f'Install error: {e}', duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        # Identify non-test modules
        # Exclude files with 'test' in basename
        modules = []
        for f in python_files:
            basename = os.path.basename(f)
            if 'test' not in basename.lower():
                # Convert path to module name
                # src/foo/bar.py -> foo.bar
                # foo/bar.py -> foo.bar
                parts = f.split(os.sep)
                if parts[0] == 'src':
                    parts = parts[1:]
                if parts[-1].endswith('.py'):
                    parts[-1] = parts[-1][:-3]
                module_name = '.'.join(parts)
                modules.append(module_name)

        if not modules:
            return GateResult(name='smoke', status=FAILED, method='import', detail='No importable modules found', duration_s=time.time()-start)

        # Prepare environment
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = [workdir, src_dir]
        if 'PYTHONPATH' in env:
            python_path.append(env['PYTHONPATH'])
        env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Try importing each module
        failures = []
        skipped_due_to_missing = False

        for module in modules:
            try:
                # Run a subprocess to import
                code = f"import {module}"
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped.
                        # This is tricky. If `import foo` fails with ModuleNotFoundError: foo, it's a failure.
                        # If `import foo` fails with ModuleNotFoundError: bar (where bar is imported by foo), it's skipped.
                        # We can't easily distinguish without parsing the error.
                        # Heuristic: If the error mentions the module name itself, it's a failure.
                        if f"No module named '{module}'" in stderr or f"No module named \"{module}\"" in stderr:
                            failures.append(f"{module}: Module not found")
                        else:
                            skipped_due_to_missing = True
                    else:
                        failures.append(f"{module}: {stderr.strip()}")

            except Exception as e:
                failures.append(f"{module}: {e}")

        duration = time.time() - start

        if failures:
            return GateResult(name='smoke', status=FAILED, method='import', detail='; '.join(failures), duration_s=duration)

        if skipped_due_to_missing:
            return GateResult(name='smoke', status=SKIPPED, method='import', detail='Skipped due to missing third-party dependencies', duration_s=duration)

        return GateResult(name='smoke', status=PASSED, method='import', detail='All modules imported', duration_s=duration)

    def _gate_tests(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        # Find test files
        test_files = []
        for f in python_files:
            if 'test' in os.path.basename(f).lower():
                test_files.append(f)

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='discover', detail='No test files found', duration_s=time.time()-start)

        # Prepare environment
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = [workdir, src_dir]
        if 'PYTHONPATH' in env:
            python_path.append(env['PYTHONPATH'])
        env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Try pytest first
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)

            # Run pytest
            result = subprocess.run(
                [self.python_executable, '-m', 'pytest', '-v', '--tb=short'] + test_files,
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='pytest', detail='All tests passed', duration_s=duration)
            else:
                # Check if it failed due to missing modules
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                    return GateResult(name='tests', status=SKIPPED, method='pytest', detail='Skipped due to missing dependencies', duration_s=duration)
                return GateResult(name='tests', status=FAILED, method='pytest', detail='Tests failed', duration_s=duration)

        except FileNotFoundError:
            # Fallback to stdlib unittest
            pass
        except Exception:
            # Fallback to stdlib unittest
            pass

        # Stdlib fallback
        # We need to run a script that imports each test file and runs tests
        # This is complex to do in a single subprocess call for multiple files.
        # Let's try to run unittest discover on the directory, but unittest discover 
        # might not pick up bare functions.

        # Better approach: Write a temporary runner script
        runner_script = os.path.join(workdir, '_test_runner.py')
        with open(runner_script, 'w') as f:
            f.write("import unittest\n")
            f.write("import sys\n")
            f.write("import os\n")
            f.write("import importlib\n")
            f.write("import traceback\n")
            f.write("\n")
            f.write("def run_tests():\n")
            f.write("    test_files = ")
            f.write(repr(test_files))
            f.write("\n")
            f.write("    suite = unittest.TestSuite()\n")
            f.write("    for tf in test_files:\n")
            f.write("        try:\n")
            f.write("            # Convert path to module name\n")
            f.write("            parts = tf.split(os.sep)\n")
            f.write("            if parts[0] == 'src':\n")
            f.write("                parts = parts[1:]\n")
            f.write("            if parts[-1].endswith('.py'):\n")
            f.write("                parts[-1] = parts[-1][:-3]\n")
            f.write("            module_name = '.'.join(parts)\n")
            f.write("            mod = importlib.import_module(module_name)\n")
            f.write("            # Load tests from module\n")
            f.write("            loader = unittest.TestLoader()\n")
            f.write("            suite.addTests(loader.loadTestsFromModule(mod))\n")
            f.write("            # Also collect bare test_* functions\n")
            f.write("            for name in dir(mod):\n")
            f.write("                if name.startswith('test_'):\n")
            f.write("                    func = getattr(mod, name)\n")
            f.write("                    if callable(func) and not isinstance(func, type):\n")
            f.write("                        try:\n")
            f.write("                            func()\n")
            f.write("                        except Exception as e:\n")
            f.write("                            print(f'FAIL: {name} in {tf}: {e}')\n")
            f.write("                            traceback.print_exc()\n")
            f.write("                            return 1\n")
            f.write("        except Exception as e:\n")
            f.write("            print(f'Error loading {tf}: {e}')\n")
            f.write("            traceback.print_exc()\n")
            f.write("            return 1\n")
            f.write("    \n")
            f.write("    runner = unittest.TextTestRunner(verbosity=2)\n")
            f.write("    result = runner.run(suite)\n")
            f.write("    return 0 if result.wasSuccessful() else 1\n")
            f.write("\n")
            f.write("if __name__ == '__main__':\n")
            f.write("    sys.exit(run_tests())\n")

        try:
            result = subprocess.run(
                [self.python_executable, runner_script],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='unittest', detail='All tests passed', duration_s=duration)
            else:
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                    return GateResult(name='tests', status=SKIPPED, method='unittest', detail='Skipped due to missing dependencies', duration_s=duration)
                return GateResult(name='tests', status=FAILED, method='unittest', detail='Tests failed', duration_s=duration)

        except Exception as e:
            return GateResult(name='tests', status=FAILED, method='unittest', detail=f'Runner error: {e}', duration_s=time.time()-start)
        finally:
            if os.path.exists(runner_script):
                os.remove(runner_script)

    def _gate_telemetry(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        if not python_files:
            return GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No Python files found', duration_s=time.time()-start)

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for f in python_files:
            full_path = os.path.join(workdir, f)
            try:
                with open(full_path, 'r', encoding='utf-8') as file:
                    tree = ast.parse(file.read())

                for node in ast.walk(tree):
                    # Check for import opentelemetry
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls
                    if isinstance(node, ast.Call):
                        func = node.func
                        # Handle method calls like tracer.start_span()
                        if isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True
                        # Handle function calls like get_tracer()
                        elif isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True

            except Exception:
                continue

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(name='telemetry', status=PASSED, method='ast_analysis', detail='Telemetry usage detected', duration_s=duration)
        else:
            detail = []
            if not has_import:
                detail.append('No opentelemetry import found')
            if not has_call:
                detail.append('No tracer/span method calls found')
            return GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='; '.join(detail), duration_s=duration)

