    def _gate_build(self, workdir: str, authored_files: List[str]) -> GateResult:
        start = time.time()

        # Check for metadata files
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None

        for mf in metadata_files:
            if mf in authored_files:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found', duration_s=time.time()-start)

        # Validate pyproject.toml if present
        if found_metadata == 'pyproject.toml':
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(name='build', status=FAILED, method='tomllib', detail='pyproject.toml missing required tables', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='tomllib', detail=f'Invalid pyproject.toml: {e}', duration_s=time.time()-start)

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)

            # Run install
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(name='build', status=PASSED, method='pip_install', detail='Installed successfully', duration_s=duration)
            else:
                return GateResult(name='build', status=FAILED, method='pip_install', detail=f'Install failed: {result.stderr}', duration_s=duration)

        except FileNotFoundError:
            return GateResult(name='build', status=SKIPPED, method='pip_install', detail='pip not available', duration_s=time.time()-start)
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method='pip_install', detail='Install timed out', duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name='build', status=FAILED, method='pip_install', detail=f'Install error: {e}', duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        # Identify non-test modules
        # Exclude files with 'test' in basename
        modules = []
        for f in python_files:
            basename = os.path.basename(f)
            if 'test' not in basename.lower():
                # Convert path to module name
                # src/foo/bar.py -> foo.bar
                # foo/bar.py -> foo.bar
                parts = f.split(os.sep)
                if parts[0] == 'src':
                    parts = parts[1:]
                if parts[-1].endswith('.py'):
                    parts[-1] = parts[-1][:-3]
                module_name = '.'.join(parts)
                modules.append(module_name)

        if not modules:
            return GateResult(name='smoke', status=FAILED, method='import', detail='No importable modules found', duration_s=time.time()-start)

        # Prepare environment
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = [workdir, src_dir]
        if 'PYTHONPATH' in env:
            python_path.append(env['PYTHONPATH'])
        env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Try importing each module
        failures = []
        skipped_due_to_missing = False

        for module in modules:
            try:
                # Run a subprocess to import
                code = f"import {module}"
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped.
                        # This is tricky. If `import foo` fails with ModuleNotFoundError: foo, it's a failure.
                        # If `import foo` fails with ModuleNotFoundError: bar (where bar is imported by foo), it's skipped.
                        # We can't easily distinguish without parsing the error.
                        # Heuristic: If the error mentions the module name itself, it's a failure.
                        if f"No module named '{module}'" in stderr or f"No module named \"{module}\"" in stderr:
                            failures.append(f"{module}: Module not found")
                        else:
                            skipped_due_to_missing = True
                    else:
                        failures.append(f"{module}: {stderr.strip()}")

            except Exception as e:
                failures.append(f"{module}: {e}")

        duration = time.time() - start

        if failures:
            return GateResult(name='smoke', status=FAILED, method='import', detail='; '.join(failures), duration_s=duration)

        if skipped_due_to_missing:
            return GateResult(name='smoke', status=SKIPPED, method='import', detail='Skipped due to missing third-party dependencies', duration_s=duration)

        return GateResult(name='smoke', status=PASSED, method='import', detail='All modules imported', duration_s=duration)

    def _gate_tests(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        # Find test files
        test_files = []
        for f in python_files:
            if 'test' in os.path.basename(f).lower():
                test_files.append(f)

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='discover', detail='No test files found', duration_s=time.time()-start)

        # Prepare environment
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = [workdir, src_dir]
        if 'PYTHONPATH' in env:
            python_path.append(env['PYTHONPATH'])
        env['PYTHONPATH'] = os.pathsep.join(python_path)

        # Try pytest first
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)

            # Run pytest
            result = subprocess.run(
                [self.python_executable, '-m', 'pytest', '-v', '--tb=short'] + test_files,
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='pytest', detail='All tests passed', duration_s=duration)
            else:
                # Check if it failed due to missing modules
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                    return GateResult(name='tests', status=SKIPPED, method='pytest', detail='Skipped due to missing dependencies', duration_s=duration)
                return GateResult(name='tests', status=FAILED, method='pytest', detail='Tests failed', duration_s=duration)

        except FileNotFoundError:
            # Fallback to stdlib unittest
            pass
        except Exception:
            # Fallback to stdlib unittest
            pass

        # Stdlib fallback
        # We need to run a script that imports each test file and runs tests
        # This is complex to do in a single subprocess call for multiple files.
        # Let's try to run unittest discover on the directory, but unittest discover 
        # might not pick up bare functions.

        # Better approach: Write a temporary runner script
        runner_script = os.path.join(workdir, '_test_runner.py')
        with open(runner_script, 'w') as f:
            f.write("import unittest\n")
            f.write("import sys\n")
            f.write("import os\n")
            f.write("import importlib\n")
            f.write("import traceback\n")
            f.write("\n")
            f.write("def run_tests():\n")
            f.write("    test_files = ")
            f.write(repr(test_files))
            f.write("\n")
            f.write("    suite = unittest.TestSuite()\n")
            f.write("    for tf in test_files:\n")
            f.write("        try:\n")
            f.write("            # Convert path to module name\n")
            f.write("            parts = tf.split(os.sep)\n")
            f.write("            if parts[0] == 'src':\n")
            f.write("                parts = parts[1:]\n")
            f.write("            if parts[-1].endswith('.py'):\n")
            f.write("                parts[-1] = parts[-1][:-3]\n")
            f.write("            module_name = '.'.join(parts)\n")
            f.write("            mod = importlib.import_module(module_name)\n")
            f.write("            # Load tests from module\n")
            f.write("            loader = unittest.TestLoader()\n")
            f.write("            suite.addTests(loader.loadTestsFromModule(mod))\n")
            f.write("            # Also collect bare test_* functions\n")
            f.write("            for name in dir(mod):\n")
            f.write("                if name.startswith('test_'):\n")
            f.write("                    func = getattr(mod, name)\n")
            f.write("                    if callable(func) and not isinstance(func, type):\n")
            f.write("                        try:\n")
            f.write("                            func()\n")
            f.write("                        except Exception as e:\n")
            f.write("                            print(f'FAIL: {name} in {tf}: {e}')\n")
            f.write("                            traceback.print_exc()\n")
            f.write("                            return 1\n")
            f.write("        except Exception as e:\n")
            f.write("            print(f'Error loading {tf}: {e}')\n")
            f.write("            traceback.print_exc()\n")
            f.write("            return 1\n")
            f.write("    \n")
            f.write("    runner = unittest.TextTestRunner(verbosity=2)\n")
            f.write("    result = runner.run(suite)\n")
            f.write("    return 0 if result.wasSuccessful() else 1\n")
            f.write("\n")
            f.write("if __name__ == '__main__':\n")
            f.write("    sys.exit(run_tests())\n")

        try:
            result = subprocess.run(
                [self.python_executable, runner_script],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='unittest', detail='All tests passed', duration_s=duration)
            else:
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                    return GateResult(name='tests', status=SKIPPED, method='unittest', detail='Skipped due to missing dependencies', duration_s=duration)
                return GateResult(name='tests', status=FAILED, method='unittest', detail='Tests failed', duration_s=duration)

        except Exception as e:
            return GateResult(name='tests', status=FAILED, method='unittest', detail=f'Runner error: {e}', duration_s=time.time()-start)
        finally:
            if os.path.exists(runner_script):
                os.remove(runner_script)

    def _gate_telemetry(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        if not python_files:
            return GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No Python files found', duration_s=time.time()-start)

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for f in python_files:
            full_path = os.path.join(workdir, f)
            try:
                with open(full_path, 'r', encoding='utf-8') as file:
                    tree = ast.parse(file.read())

                for node in ast.walk(tree):
                    # Check for import opentelemetry
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls
                    if isinstance(node, ast.Call):
                        func = node.func
                        # Handle method calls like tracer.start_span()
                        if isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True
                        # Handle function calls like get_tracer()
                        elif isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True

            except Exception:
                continue

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(name='telemetry', status=PASSED, method='ast_analysis', detail='Telemetry usage detected', duration_s=duration)
        else:
            detail = []
            if not has_import:
                detail.append('No opentelemetry import found')
            if not has_call:
                detail.append('No tracer/span method calls found')
            return GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='; '.join(detail), duration_s=duration)
